  static List<Subject> getSubjectsForSlot(String dayOfWeek, int period, {String? facultyFilter}) {
    return sampleSubjects.where((s) {
      final matchSlot = s.dayOfWeek == dayOfWeek && s.period == period;
      if (!matchSlot) return false;
      if (facultyFilter != null && facultyFilter.isNotEmpty && facultyFilter != 'すべて') {
        return s.faculty.contains(facultyFilter);
      }
      return true;
    }).toList();
  }

  static Subject? findById(String id) {
    try {
      return sampleSubjects.firstWhere((s) => s.id == id);
    } catch (_) {
      return null;
    }
  }
}